"""Assistant tab — renders HTML status page and triggers refresh commands.

Displays an HTML file from ~/source/personal-assistant/ and provides
a button to run a refresh command. Before refreshing the HTML, stages
and commits changes in the working directory.
"""

from __future__ import annotations

import logging
import subprocess
import threading
import tkinter as tk
from pathlib import Path
from typing import Any

from personal_assistant.config import (
    BG_OUTPUT,
    BG_WINDOW,
    FG_DIM,
    FG_TEXT,
    FONT_BODY,
    PAD,
)

logger = logging.getLogger(__name__)

COLOR_BTN = "#4e4e4e"
COLOR_ACTIVE = "#61afef"

# CSS injected into HTML frames for spacing
SPACING_CSS = (
    "body { line-height: 1.5; }"
    " h1, h2, h3, h4, h5 { margin-top: 1.2em; margin-bottom: 0.4em; }"
    " p { margin-top: 0.4em; margin-bottom: 0.4em; }"
    " ul, ol { margin-top: 0.4em; margin-bottom: 0.4em; }"
    " li { margin-bottom: 0.2em; }"
    " table { margin-bottom: 1em; }"
    " td, th { padding: 4px 8px; }"
)

# Paths — placeholder directory and files
ASSISTANT_DIR = Path.home() / "Downloads" / "personal-assistant"
ASSISTANT_HTML = ASSISTANT_DIR / "summary.html"
ACTIONS_HTML = ASSISTANT_DIR / "actions.html"
REFRESH_COMMAND = str('claude -p "/personal-assistant"')


class AssistantTab:
    """Assistant tab for the PA dashboard.

    Renders an HTML page and provides a refresh button that:
    1. Runs a shell command to regenerate the HTML
    2. Stages and commits changes in the working directory
    3. Reloads the HTML display
    """

    def __init__(
        self,
        parent: tk.Frame,
        root: tk.Tk,
        *,
        on_actions_refresh: Any = None,
        console_log: Any = None,
        notify_tab: Any = None,
    ) -> None:
        self._parent = parent
        self._root = root
        self._on_actions_refresh = on_actions_refresh
        self._console_log = console_log
        self._notify_tab = notify_tab
        self._running = False
        self._age_timer: str | None = None
        self._build()
        self._start_age_timer()

    def _build(self) -> None:
        # Control bar
        controls = tk.Frame(self._parent, bg=BG_WINDOW)
        controls.pack(fill=tk.X, padx=PAD, pady=(PAD, 0))

        self._status_var = tk.StringVar(value="")
        tk.Label(
            controls,
            textvariable=self._status_var,
            bg=BG_WINDOW,
            fg=FG_DIM,
            font=FONT_BODY,
        ).pack(side=tk.LEFT)

        self._refresh_btn = tk.Button(
            controls,
            text="Refresh",
            command=self._on_refresh,
            bg=COLOR_BTN,
            fg=FG_TEXT,
            font=FONT_BODY,
            relief=tk.FLAT,
            activebackground="#5e5e5e",
            cursor="hand2",
            padx=8,
        )
        self._refresh_btn.pack(side=tk.RIGHT)

        tk.Button(
            controls,
            text="\U0001f504",
            command=self._load_html,
            bg=COLOR_BTN,
            fg=FG_TEXT,
            font=FONT_BODY,
            relief=tk.FLAT,
            activebackground="#5e5e5e",
            cursor="hand2",
            padx=4,
        ).pack(side=tk.RIGHT, padx=(0, 4))

        # HTML display
        self._html_frame: Any = None
        self._build_html_frame()

    def _build_html_frame(self) -> None:
        """Build or rebuild the HTML display frame."""
        try:
            from tkinterweb import HtmlFrame

            if self._html_frame is not None:
                self._html_frame.destroy()

            import webbrowser

            self._html_frame = HtmlFrame(
                self._parent,
                messages_enabled=False,
                dark_theme_enabled=True,
                on_link_click=lambda url: webbrowser.open(url),
            )
            self._html_frame.pack(fill=tk.BOTH, expand=True, padx=PAD, pady=PAD)
            self._load_html()
        except ImportError:
            # Fallback: plain text display
            fallback = tk.Text(
                self._parent,
                bg=BG_OUTPUT,
                fg=FG_TEXT,
                font=FONT_BODY,
                wrap=tk.WORD,
                state=tk.DISABLED,
                highlightthickness=0,
            )
            fallback.pack(fill=tk.BOTH, expand=True, padx=PAD, pady=PAD)
            fallback.configure(state=tk.NORMAL)
            fallback.insert(
                "1.0",
                "tkinterweb not installed. Run: pip install tkinterweb[recommended]",
            )
            fallback.configure(state=tk.DISABLED)

    def _load_html(self) -> None:
        """Load the HTML file into the display."""
        if self._html_frame is None:
            return
        if ASSISTANT_HTML.exists():
            content = ASSISTANT_HTML.read_text(encoding="utf-8")
            self._html_frame.load_html(content)
            self._html_frame.add_css(SPACING_CSS)
        else:
            body = (
                "<html><body style='background:#252525;color:#ccc;"
                "font-family:sans-serif;padding:20px'>"
                "<p>No status page found at:</p>"
                f"<code>{ASSISTANT_HTML}</code>"
                "</body></html>"
            )
            self._html_frame.load_html(body)

    def _start_age_timer(self) -> None:
        """Start updating the page age every 10 seconds."""
        self._update_age()

    def _update_age(self) -> None:
        """Update the status label with the age of the HTML file."""
        if self._running:
            self._age_timer = self._root.after(10_000, self._update_age)
            return
        if ASSISTANT_HTML.exists():
            import time

            mtime = ASSISTANT_HTML.stat().st_mtime
            age_seconds = int(time.time() - mtime)
            if age_seconds < 60:
                age_text = f"{age_seconds}s ago"
            elif age_seconds < 3600:
                age_text = f"{age_seconds // 60}m ago"
            elif age_seconds < 86400:
                hours = age_seconds // 3600
                minutes = (age_seconds % 3600) // 60
                age_text = f"{hours}h {minutes}m ago"
            else:
                days = age_seconds // 86400
                age_text = f"{days}d ago"
            self._status_var.set(f"Updated {age_text}")
        else:
            self._status_var.set("No status page")
        self._age_timer = self._root.after(10_000, self._update_age)

    def _on_refresh(self) -> None:
        """Run the refresh command in the background."""
        if self._running:
            return
        self._running = True
        self._refresh_btn.configure(state="disabled")
        self._status_var.set("Refreshing...")
        self._log("Assistant: starting refresh...", "progress")

        thread = threading.Thread(
            target=self._do_refresh,
            daemon=True,
            name="assistant-refresh",
        )
        thread.start()

    def _do_refresh(self) -> None:
        """Background: commit previous state, run refresh, reload HTML."""
        try:
            # Stage and commit previous changes before refresh
            self._git_commit()

            # Run the refresh command in the assistant directory
            result = subprocess.run(
                REFRESH_COMMAND,
                cwd=str(ASSISTANT_DIR),
                capture_output=True,
                text=True,
                timeout=600,
                check=False,
                shell=True,
            )
            if result.returncode != 0:
                self._log(
                    f"Assistant: refresh command failed: {result.stderr.strip()[:200]}",
                    "error",
                )

            # Reload HTML on the main thread
            self._root.after(0, self._on_refresh_complete)
        except subprocess.TimeoutExpired:
            self._log("Assistant: refresh command timed out", "error")
            self._root.after(0, self._on_refresh_complete)
        except Exception as exc:
            logger.exception("Assistant refresh failed")
            self._log(f"Assistant: refresh error: {exc}", "error")
            self._root.after(0, self._on_refresh_complete)

    def _git_commit(self) -> None:
        """Stage and commit changes in the assistant directory."""
        if not (ASSISTANT_DIR / ".git").is_dir():
            return
        try:
            subprocess.run(
                ["git", "add", "."],
                cwd=str(ASSISTANT_DIR),
                capture_output=True,
                timeout=10,
                check=False,
            )
            subprocess.run(
                ["git", "commit", "-m", "Auto-commit: assistant refresh"],
                cwd=str(ASSISTANT_DIR),
                capture_output=True,
                timeout=10,
                check=False,
            )
            subprocess.run(
                ["git", "push", "origin", "main"],
                cwd=str(ASSISTANT_DIR),
                capture_output=True,
                timeout=10,
                check=False,
            )
        except Exception as exc:
            logger.debug("Git commit in assistant dir failed: %s", exc)

    def _on_refresh_complete(self) -> None:
        """Main thread: reload HTML and re-enable button."""
        self._load_html()
        self._running = False
        self._refresh_btn.configure(state="normal")
        self._update_age()
        self._log("Assistant: refresh complete", "success")

        # Notify tabs
        if self._notify_tab is not None:
            self._notify_tab("Assistant")
            self._notify_tab("Actions")

        # Also refresh the Actions tab
        if self._on_actions_refresh is not None:
            try:
                self._on_actions_refresh()
            except Exception:
                pass

    def _log(self, message: str, tag: str = "info") -> None:
        """Forward to dashboard console."""
        if self._console_log is not None:
            try:
                self._root.after(0, self._console_log, message, tag)
            except Exception:
                pass
